    ld.param.u32 %rD2,      [D2_param];
    ld.param.f32 %f_eps,    [eps_param];
    // Thread/block info
    mov.u32 %rTid,    %tid.x;
    mov.u32 %rBix,    %ctaid.x;
    mov.u32 %rBiy,    %ctaid.y;
    mov.u32 %rNtid,   %ntid.x;
    mov.u32 %rNbix,   %nctaid.x;
    // Compute M = F * D1 * D2
    mul.lo.u32 %rM, %rF, %rD1;
    mul.lo.u32 %rM, %rM, %rD2;
    // stride = gridDim.x * blockDim.x
    mul.lo.u32 %rStride, %rNbix, %rNtid;
    // starting m = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32 %rTmp0, %rBix, %rNtid;
    add.u32    %rMIdx, %rTmp0, %rTid;
    // Local accumulators
    mov.f32 %fSum,   0f00000000; // 0.0
    mov.f32 %fSumsq, 0f00000000; // 0.0
    // Loop over elements for partial sums
LOOP_SUM:
    setp.ge.u32 %p0, %rMIdx, %rM;
    @%p0 bra LOOP_SUM_DONE;
    // idx64 = by * M + m
    mul.wide.u32 %rdNM, %rBiy, %rM;
    cvt.u64.u32  %rdm,  %rMIdx;
    add.s64      %rdIndex, %rdNM, %rdm;
    // x address = x_ptr + (idx64 * 4)
    shl.b64 %rdByteOff, %rdIndex, 2;
    add.s64 %rdXAddr, %rdX, %rdByteOff;
    // load x
    ld.global.f32 %fX, [%rdXAddr];
    // accumulate
    add.f32 %fSum, %fSum, %fX;
    mul.f32 %fTmp, %fX, %fX;
    add.f32 %fSumsq, %fSumsq, %fTmp;
    // next
    add.u32 %rMIdx, %rMIdx, %rStride;
    bra LOOP_SUM;
LOOP_SUM_DONE:
    // Atomically add block's thread-local sums to global sums for this sample
    cvt.u64.u32 %rdNy, %rBiy;
    shl.b64     %rdOffN4, %rdNy, 2;
    add.s64 %rdSAddr,  %rdSums,  %rdOffN4;
    atom.global.add.f32 %fOld0, [%rdSAddr], %fSum;
    add.s64 %rdSSAddr, %rdSumsq, %rdOffN4;
    atom.global.add.f32 %fOld1, [%rdSSAddr], %fSumsq;
    // Ensure all threads finished atomics and make them globally visible before counting
    bar.sync 0;
    membar.gl;
    bar.sync 0;
    // Thread 0 per block increments the completion counter
    setp.ne.u32 %p1, %rTid, 0;
    @%p1 bra AFTER_COUNT;
    add.s64 %rdCAddr, %rdCounts, %rdOffN4;
    mov.u32 %rOne32, 1;
    // fence already executed by all threads above
    atom.global.add.u32 %rOldCount, [%rdCAddr], %rOne32;
    // If this was the last block for the sample, compute mean/invstd and set ready flag
    add.u32 %rNbixMinus1, %rNbix, 0xffffffff; // gridDim.x - 1
    setp.ne.u32 %p2, %rOldCount, %rNbixMinus1;
    @%p2 bra NOT_LAST;
    // We are the last block (oldCount == gridDim.x - 1)
    // Wait until counter reaches gridDim.x to ensure all producers finished and published
RECHECK_COUNTS:
    ld.global.u32 %rTmp1, [%rdCAddr];
    setp.lt.u32 %p5, %rTmp1, %rNbix;
    @%p5 bra RECHECK_COUNTS;
    // Acquire: ensure visibility of all prior global writes before reading totals
    membar.gl;
    // Load totals
    ld.global.f32 %fTotSum, [%rdSAddr];
    ld.global.f32 %fTotSS,  [%rdSSAddr];
    // mean = totSum / M
    cvt.rn.f32.u32 %fM, %rM;
    div.rn.f32 %fMean, %fTotSum, %fM;
    // var = totSS / M - mean*mean
    div.rn.f32 %fVar, %fTotSS, %fM;
    mul.f32    %fMM, %fMean, %fMean;
    sub.f32    %fVar, %fVar, %fMM;
    // var_eps = var + eps
    add.f32 %fVarEps, %fVar, %f_eps;
    // invstd = 1.0 / sqrt(var_eps)
    sqrt.rn.f32 %fSqrt, %fVarEps;
    mov.f32 %fOne, 0f3f800000; // 1.0
    div.rn.f32 %fInvstd, %fOne, %fSqrt;
    // Store mean and invstd
    add.s64 %rdMeanAddr, %rdMeans, %rdOffN4;
    st.global.f32 [%rdMeanAddr], %fMean;
    add.s64 %rdInvAddr, %rdInvstd, %rdOffN4;
    st.global.f32 [%rdInvAddr], %fInvstd;
    // Memory fence and set ready flag
    membar.gl;
    add.s64 %rdFlagAddrW, %rdFlags, %rdOffN4;
    st.global.release.u32 [%rdFlagAddrW], %rOne32
    bra AFTER_COUNT;
NOT_LAST:
    // not last block: nothing to do here
AFTER_COUNT:
    // All threads wait until flag is set for this sample
WAIT_FLAG:
    add.s64 %rdFlagAddr, %rdFlags, %rdOffN4;
    ld.global.acquire.u32 %rFlag, [%rdFlagAddr]
    setp.eq.u32 %p3, %rFlag, 0;
    @%p3 bra WAIT_FLAG;
    // Load mean and invstd for normalization
    membar.gl;
    add.s64 %rdMeanAddr2, %rdMeans, %rdOffN4;
    ld.global.f32 %fMean2, [%rdMeanAddr2];
    add.s64 %rdInvAddr2, %rdInvstd, %rdOffN4;
    ld.global.f32 %fInvstd2, [%rdInvAddr2];
    // Reset m for normalization pass
    mul.lo.u32 %rTmp1, %rBix, %rNtid;
    add.u32    %rMIdx2, %rTmp1, %rTid;
LOOP_NORM:
    setp.ge.u32 %p4, %rMIdx2, %rM;
    @%p4 bra LOOP_NORM_DONE;
    // idx64 = by * M + m
    mul.wide.u32 %rdNM2, %rBiy, %rM;
    cvt.u64.u32  %rdm2,  %rMIdx2;
    add.s64      %rdIndex2, %rdNM2, %rdm2;
    // byte offsets
    shl.b64 %rdByteOff2, %rdIndex2, 2;
    // addresses
    add.s64 %rdXAddr2, %rdX, %rdByteOff2;
    add.s64 %rdYAddr2, %rdY, %rdByteOff2;
    // load input
    ld.global.f32 %fX2, [%rdXAddr2];
    // load weight and bias using m-only offset
    shl.b64 %rdWBOff, %rdm2, 2;
    add.s64 %rdWAddr2, %rdW, %rdWBOff;
    add.s64 %rdBAddr2, %rdB, %rdWBOff;
    ld.global.f32 %fW2, [%rdWAddr2];
    ld.global.f32 %fB2, [%rdBAddr2];
    // y = ((x - mean) * invstd) * w + b
    sub.f32    %fT0, %fX2, %fMean2;
    mul.f32    %fT1, %fT0, %fInvstd2;
    fma.rn.f32 %fY,  %fT1, %fW2, %fB2;
    // store
    st.global.f32 [%rdYAddr2], %fY;
    // next
    add.u32 %rMIdx2, %rMIdx2, %rStride;
    bra LOOP_NORM;
LOOP_NORM_DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_4d_onekernel")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        # Match LayerNorm constructor parameters and behavior
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        # Shapes
        assert x.dim() == 4, "Expected input of shape (N, F, D1, D2)"
        N, F, D1, D2 = x.shape
        assert (F, D1, D2) == self.normalized_shape, "normalized_shape must match last 3 dims of input"

        y = torch.empty_like(x)

        # Workspace buffers per-sample
        device = x.device
        sums   = torch.zeros(N, dtype=torch.float32, device=device)
        sumsq  = torch.zeros(N, dtype=torch.float32, device=device)
        means  = torch.empty(N, dtype=torch.float32, device=device)
        invstd = torch.empty(N, dtype=torch.float32, device=device)
        counts = torch.zeros(N, dtype=torch.int32, device=device)
        flags  = torch.zeros(N, dtype=torch.int32, device=device)

        # Grid/block configuration
        block_x = 256
        M = F * D1 * D2
        # Choose a reasonable number of blocks per sample
        grid_x = max(1, min(1024, (M + block_x - 1) // block_x))
        grid = (grid_x, N, 1)
        block = (block_x, 1, 1)

        module = _get_ptx_module()
        module.launch(
            "layernorm_4d_onekernel",
            grid=grid,
            block=block,
            arguments=[
                x, y, self.weight, self.bias,
                sums, sumsq, means, invstd, counts, flags,
                i32(N), i32(F), i32(D1), i32(D2), f32(self.eps)
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
